export const partById = Object.fromEntries(parts.map(p=>[p.id,p]));

export function statusAt(part,time){
 if(part.kind!=='instrument'||!Number.isFinite(time))return null;
 if(!part.history){
  const day=new Date(time*1000).toISOString().slice(0,10);
  if(operating.has(part.id)&&day==='2026-04-17')return 'Работал согласно сводке NASA от 17 апреля 2026 года.';
  return 'Нет подтверждённого состояния для этой даты.';
 }
 const [first,last,notes]=part.history;
 const day=new Date(time*1000).toISOString().slice(0,10);
 if(day===first||day===last)return 'Подтверждён день отключения, точное время не указано.';
 if(last&&day>first&&day<last)return 'Широкоугольная камера отключена. Узкоугольную ещё не отключили.';
 if(day>(last??first))return 'Отключено. '+(notes??('Дата отключения: '+first+'.'));
 return 'До подтверждённого отключения. Состояние в эту минуту не установлено.';
}
